import{_ as a,o as e,c as s,ae as r}from"./chunks/framework.RRduUuAx.js";const m=JSON.parse('{"title":"机器学习入门（示例）","description":"","frontmatter":{},"headers":[],"relativePath":"cs/ml-intro.md","filePath":"cs/ml-intro.md"}'),i={name:"cs/ml-intro.md"};function l(o,t,n,d,c,h){return e(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="机器学习入门-示例" tabindex="-1">机器学习入门（示例） <a class="header-anchor" href="#机器学习入门-示例" aria-label="Permalink to &quot;机器学习入门（示例）&quot;">​</a></h1><h2 id="监督学习流水线-口头版" tabindex="-1">监督学习流水线（口头版） <a class="header-anchor" href="#监督学习流水线-口头版" aria-label="Permalink to &quot;监督学习流水线（口头版）&quot;">​</a></h2><ol><li><strong>数据</strong>：划分 train / validation / test；泄漏检查。</li><li><strong>表示</strong>：特征工程或表征学习。</li><li><strong>模型</strong>：线性模型 → 树模型 → 神经网络（按复杂度递进）。</li><li><strong>优化</strong>：损失函数 + 正则；学习率与 batch size。</li><li><strong>评估</strong>：任务相关指标（准确率、F1、MSE…）。</li></ol><h2 id="小例子-线性回归" tabindex="-1">小例子：线性回归 <a class="header-anchor" href="#小例子-线性回归" aria-label="Permalink to &quot;小例子：线性回归&quot;">​</a></h2><p>目标：近似 <strong>y ≈ wᵀx + b</strong>（占位记号）。</p><p>训练时常用均方误差（写法示意）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L = (1/N) × Σᵢ ( yᵢ − (wᵀxᵢ + b) )²</span></span></code></pre></div><p>（正文仅为排版演示，不涉及推导细节。）</p><h2 id="术语备忘录-假" tabindex="-1">术语备忘录（假） <a class="header-anchor" href="#术语备忘录-假" aria-label="Permalink to &quot;术语备忘录（假）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>一句话</th></tr></thead><tbody><tr><td>过拟合</td><td>训练好、泛化差；对照 validation 曲线判断</td></tr><tr><td>偏差–方差</td><td>简化图解：模型容量与数据噪声的拉锯</td></tr></tbody></table><details class="details custom-block"><summary>延伸阅读占位</summary><ul><li>《统计学习方法》目录对照</li><li>Andrew Ng 机器学习课程章节映射</li></ul></details>',11)])])}const u=a(i,[["render",l]]);export{m as __pageData,u as default};
